<?php
namespace App\Jobs;use App\Models\MediaAsset;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;
class PrepareFaceProcessing implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public function __construct(public int $assetId){$this->onQueue('media-default');}public function middleware():array{return[(new WithoutOverlapping('face-prep-'.$this->assetId))->expireAfter(120)->dontRelease()];}public function handle():void{$asset=MediaAsset::findOrFail($this->assetId);if($asset->state!=='completed'||!$asset->variant('optimized')){$this->release(15);return;}/* Readiness only: biometric extraction belongs to Milestone 1D. */}}
